import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Detect if opponent is mostly cooperative recently.
    recent = history[-20:]
    opp_c = sum(1 for _, o in recent if o == 'C')
    my_c = sum(1 for m, _ in recent if m == 'C')

    if n < 10:
        return 'C'

    # If opponent just defected after we cooperated, retaliate briefly.
    last_mine, last_opp = history[-1]
    if last_opp == 'D' and last_mine == 'C':
        # Tit-for-tat style retaliation, but occasionally forgive.
        if rng.random() < 0.1:
            return 'C'
        return 'D'

    # If opponent defected and we defected, consider forgiving.
    if last_opp == 'D' and last_mine == 'D':
        # Try to break defection spirals.
        run = 0
        for m, o in reversed(history):
            if m == 'D' and o == 'D':
                run += 1
            else:
                break
        if run >= 3 and rng.random() < 0.35:
            return 'C'
        return 'D'

    # Opponent cooperated. Cooperate, but probe occasionally if we've been nice.
    if last_opp == 'C':
        if n >= 50 and rng.random() < 0.02 and my_c > opp_c + 5:
            return 'D'
        return 'C'

    return 'C'
